"""QQ-Qwen Image 2.1 一键出图。

内部复刻 ComfyUI 官方 `Text Encode Qwen Image 2.1`（comfy_extras/nodes_qwen.py 的
TextEncodeQwenImage21）的编码逻辑，并串上官方 KSampler 与 VAEDecode，一个节点直接出图。
参考图为单个列表输入口 `参考图`：接 QQ-多媒体加载 的 multi output（列表）或普通 batch
张量时按顺序展平，每一帧就是一张参考图，与官方逐口接线等价。
"""

from __future__ import annotations

import math
from typing import Any

import torch

MAX_ENCODE_REFERENCE_IMAGES = 16
REFERENCE_INPUT = "参考图"


def _first(value: Any, default: Any = None) -> Any:
    """INPUT_IS_LIST 会把每个输入包成列表，这里统一取第一个值。"""
    if isinstance(value, (list, tuple)):
        value = value[0] if len(value) else default
    return default if value is None else value


def _append_frames(value: Any, sink: list[torch.Tensor], label: str) -> None:
    if value is None:
        return
    if isinstance(value, torch.Tensor):
        tensor = value.detach()
        if tensor.ndim == 3:
            tensor = tensor.unsqueeze(0)
        if tensor.ndim != 4:
            raise ValueError(f"{label} 的图片张量维度不正确（需要 HWC 或 BHWC）")
        for index in range(tensor.shape[0]):
            sink.append(tensor[index : index + 1])
        return
    if isinstance(value, (list, tuple)):
        for item in value:
            _append_frames(item, sink, label)
        return
    raise ValueError(f"{label} 只接受 IMAGE 张量")


def _collect_images(value: Any) -> list[torch.Tensor]:
    images: list[torch.Tensor] = []
    _append_frames(value, images, REFERENCE_INPUT)
    if len(images) > MAX_ENCODE_REFERENCE_IMAGES:
        raise ValueError(f"最多支持 {MAX_ENCODE_REFERENCE_IMAGES} 张参考图，当前 {len(images)} 张")
    return images


def _resize_reference(image: torch.Tensor, resolution: int):
    """官方规则：缩到约 resolution x resolution、32 的倍数、保持宽高比；0 表示各自取整到 32。"""
    from comfy import utils as comfy_utils

    samples = image[:1].movedim(-1, 1)
    if resolution > 0:
        ratio = samples.shape[3] / samples.shape[2]
        width = round(math.sqrt(resolution * resolution * ratio) / 32) * 32
        height = round(math.sqrt(resolution * resolution / ratio) / 32) * 32
    else:
        width, height = round(samples.shape[3] / 32) * 32, round(samples.shape[2] / 32) * 32
    width, height = max(32, width), max(32, height)
    if (width, height) == (samples.shape[3], samples.shape[2]):
        return image[:1], width, height
    upscaled = comfy_utils.common_upscale(samples, width, height, "lanczos", "disabled")
    return upscaled.movedim(1, -1), width, height


def _encode_references(clip, prompt, negative_prompt, vae, resolution, images):
    """官方 TextEncodeQwenImage21 的核心：正负条件 + 按第一张参考图尺寸的空 latent。"""
    from comfy import model_management
    import node_helpers

    ref_latents = []
    images_vl = []
    latent_w = latent_h = resolution or 1024
    for image in images:
        # 和官方一致：文本编码器和 VAE 用同一次缩放，保证每个视觉槽对应 2x2 latent
        resized, width, height = _resize_reference(image, resolution)
        if not images_vl:
            latent_w, latent_h = width, height
        rgb = resized[:, :, :, :3]
        if resized.shape[-1] > 3:
            # 视觉塔看「alpha 叠在白底上」的结果，VAE 保留四通道
            rgb = rgb * resized[:, :, :, 3:] + (1.0 - resized[:, :, :, 3:])
        images_vl.append(rgb)
        if vae is not None:
            ref_latents.append(vae.encode(resized))

    keep_vision = len(ref_latents) == 0
    positive = clip.encode_from_tokens_scheduled(
        clip.tokenize(prompt, images=images_vl, keep_vision=keep_vision, prevent_empty_text=True)
    )
    negative = clip.encode_from_tokens_scheduled(
        clip.tokenize(negative_prompt, images=images_vl, keep_vision=keep_vision, prevent_empty_text=True)
    )
    if ref_latents:
        positive = node_helpers.conditioning_set_values(
            positive, {"reference_latents": ref_latents}, append=True
        )
        negative = node_helpers.conditioning_set_values(
            negative, {"reference_latents": ref_latents}, append=True
        )
    latent = torch.zeros(
        [1, 64, latent_h // 16, latent_w // 16],
        device=model_management.intermediate_device(),
    )
    return (positive, negative, {"samples": latent})


def _sampler_choices():
    try:
        import comfy.samplers

        return list(comfy.samplers.KSampler.SAMPLERS), list(comfy.samplers.KSampler.SCHEDULERS)
    except Exception:
        return ["euler"], ["normal"]


class QQQwenImage21AllInOne:
    """编码 + K采样 + VAE 解码一条龙，省掉 KSampler / VAEDecode 两条连线。"""

    CATEGORY = "QQ/图像生成"
    FUNCTION = "run"
    INPUT_IS_LIST = True
    RETURN_TYPES = ("IMAGE",)
    RETURN_NAMES = ("图像",)
    DESCRIPTION = (
        "把 QQ-Text Encode Qwen Image 2.1、K采样器、VAE 解码三个节点合成一个："
        "内部先按官方规则编码正负条件和参考图 latent，再跑 K 采样，最后 VAE 解码直接出图。"
        "参考图仍是单个列表口，接 QQ-多媒体加载 的 multi output 或 batch 张量按顺序展平，最多 16 张。"
        "采样控件与官方 KSampler 完全一致（seed/steps/cfg/sampler_name/scheduler/denoise）。"
    )

    @classmethod
    def INPUT_TYPES(cls):
        samplers, schedulers = _sampler_choices()
        return {
            "required": {
                "model": ("MODEL",),
                "clip": ("CLIP",),
                "vae": ("VAE",),
                "prompt": ("STRING", {"multiline": True, "dynamic_prompts": True, "default": ""}),
                "negative_prompt": ("STRING", {"multiline": True, "dynamic_prompts": True, "default": ""}),
                "resolution": (
                    "INT",
                    {
                        "default": 1024,
                        "min": 0,
                        "max": 4096,
                        "step": 32,
                        "tooltip": "参考图缩到约 resolution x resolution、32 的倍数、保持宽高比；0 表示保持各自尺寸。",
                    },
                ),
                "seed": (
                    "INT",
                    {"default": 0, "min": 0, "max": 0xFFFFFFFFFFFFFFFF, "control_after_generate": True},
                ),
                "steps": ("INT", {"default": 20, "min": 1, "max": 10000}),
                "cfg": ("FLOAT", {"default": 8.0, "min": 0.0, "max": 100.0, "step": 0.1, "round": 0.01}),
                "sampler_name": (samplers,),
                "scheduler": (schedulers,),
                "denoise": ("FLOAT", {"default": 1.0, "min": 0.0, "max": 1.0, "step": 0.01}),
            },
            "optional": {
                REFERENCE_INPUT: (
                    "IMAGE",
                    {
                        "tooltip": (
                            "单口多图，顺序即参考图序号，最多 16 张。"
                            "可直接接 QQ-多媒体加载 的 multi output，也可接 Load Image 等 batch 张量。"
                        ),
                    },
                ),
            },
        }

    def run(self, model, clip, vae, prompt, negative_prompt, resolution, seed, steps, cfg,
            sampler_name, scheduler, denoise, **kwargs):
        from nodes import KSampler, VAEDecode

        positive, negative, latent = _encode_references(
            _first(clip),
            str(_first(prompt, "") or ""),
            str(_first(negative_prompt, "") or ""),
            _first(vae),
            int(_first(resolution, 1024) or 0),
            _collect_images(kwargs.get(REFERENCE_INPUT)),
        )
        (samples,) = KSampler().sample(
            model=_first(model),
            seed=int(_first(seed, 0) or 0),
            steps=int(_first(steps, 20) or 20),
            cfg=float(_first(cfg, 8.0)),
            sampler_name=str(_first(sampler_name, "euler")),
            scheduler=str(_first(scheduler, "normal")),
            positive=positive,
            negative=negative,
            latent_image=latent,
            denoise=float(_first(denoise, 1.0)),
        )
        (image,) = VAEDecode().decode(vae=_first(vae), samples=samples)
        return (image,)


NODE_CLASS_MAPPINGS = {
    "QQQwenImage21AllInOne": QQQwenImage21AllInOne,
}
NODE_DISPLAY_NAME_MAPPINGS = {
    "QQQwenImage21AllInOne": "QQ-Qwen Image 2.1 一键出图(编码+K采样+VAE解码)",
}
